\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.17}
\begin{document}
\begin{tikzpicture}
\begin{axis}[
    axis equal,
    xlabel={$x$}, ylabel={$y$ / $z$},
    xmin=0, xmax=4,
    ymin=-3, ymax=2,
    width=10cm, height=10cm,
    title={Traces of $(x-2)^2-(y+1)^2+(z-1)^2=1$},
    legend pos=south east,
]
\addplot[blue, thick, domain=0:360, samples=200] ({2+cos(x)}, {1+sin(x)});
\addlegendentry{$y=-1$ trace (circle)}
\addplot[green!60!black, dashed, thick, domain=1.05:2.95, samples=200] ({x}, {-1+sqrt((x-2)^2-1)});
\addplot[green!60!black, dashed, thick, domain=1.05:2.95, samples=200] ({x}, {-1-sqrt((x-2)^2-1)});
\addlegendentry{$z=1$ trace (hyperbola)}
\addplot[only marks, mark=*, red] coordinates {(2,-1)};
\end{axis}
\end{tikzpicture}
\end{document}

